from fractions import Fraction as Fr

# Exact Laurent polynomials in tau and E = e^s, stored as {(i, k): coeff} for tau^i * E^k.
# d/ds of E^k equals k*E^k, so ds() is exact.

def clean(d):
    return {k: v for k, v in d.items() if v != 0}

def add(a, b):
    r = dict(a)
    for k, v in b.items():
        r[k] = r.get(k, 0) + v
    return clean(r)

def neg(a):
    return {k: -v for k, v in a.items()}

def sub(a, b):
    return add(a, neg(b))

def mul(a, b):
    r = {}
    for (i1, k1), v1 in a.items():
        for (i2, k2), v2 in b.items():
            key = (i1 + i2, k1 + k2)
            r[key] = r.get(key, 0) + v1 * v2
    return clean(r)

def ds(a):
    return clean({k: v * k[1] for k, v in a.items()})

def at_s0(a):
    # Evaluate at s = 0 (E = 1); returns {tau_power: coeff}
    r = {}
    for (i, _), v in a.items():
        r[i] = r.get(i, 0) + v
    return clean(r)

def m(c, i, k):
    return {(i, k): Fr(c)}

ONE = m(1, 0, 0)

# Candidate characteristic curves x(tau,s), y(tau,s), u(tau,s)
options = {
    1: (add(m(3, 1, 1), m(-3, 1, 0)),
        add(m(Fr(1, 2), 1, -1), m(Fr(1, 2), 1, 0)),
        m(1, 2, -2)),
    2: (add(m(2, 1, 1), m(-2, 1, 0)),
        add(m(2, 1, 2), m(-1, 1, 0)),
        add(m(Fr(1, 2), 2, 0), m(Fr(1, 2), 2, -2))),
    3: (add(m(2, 1, 1), m(-2, 1, 0)),
        add(m(Fr(1, 2), 1, 1), m(Fr(1, 2), 1, 0)),
        m(1, 2, 2)),
    4: (add(m(1, 1, -1), m(-1, 1, 0)),
        add(m(-2, 1, -1), m(3, 1, 0)),
        add(m(2, 2, -2), m(-1, 2, 0))),
}

def check(n):
    x, y, u = options[n]
    # Charpit: dx/ds = q and dy/ds = p, so p = y_s and q = x_s
    p = ds(y)
    q = ds(x)
    results = {}
    # Initial curve: x=0, y=tau, u=tau^2 at s=0
    results["init_x0"] = at_s0(x) == {}
    results["init_y0"] = at_s0(y) == {1: Fr(1)}
    results["init_u0"] = at_s0(u) == {2: Fr(1)}
    # Complete integral / PDE: p*q - u = 0 identically
    results["PDE_pq_eq_u"] = sub(mul(p, q), u) == {}
    # Charpit ODEs: du/ds = 2pq, dp/ds = p, dq/ds = q
    results["ODE_du"] = sub(ds(u), mul(m(2, 0, 0), mul(p, q))) == {}
    results["ODE_dp"] = sub(ds(p), p) == {}
    results["ODE_dq"] = sub(ds(q), q) == {}
    # Strip condition at s=0: dx0/dtau=0, dy0/dtau=1, du0/dtau=2tau => q0 = 2tau
    q0 = at_s0(q)
    p0 = at_s0(p)
    results["strip_q0_eq_2tau"] = q0 == {1: Fr(2)}
    results["strip_p0_eq_tau_over_2"] = p0 == {1: Fr(1, 2)}
    return results, p, q

passing = []
for n in (1, 2, 3, 4):
    res, p, q = check(n)
    ok = all(res.values())
    print(f"Option {n}: " + ("CHECK PASS" if ok else "CHECK FAIL"))
    for key, val in res.items():
        print(f"  {key}: {val}")
    if ok:
        passing.append(n)

print("Passing options:", passing)

# Derived result by Charpit: p = tau/2 e^s, q = 2 tau e^s, u = tau^2 e^{2s}
_, p3, q3 = check(3)
print("Option 3 p(s) coefficients:", p3)
print("Option 3 q(s) coefficients:", q3)

# Submitted answer corresponds to option 1
submitted = 1
if submitted in passing and passing == [submitted]:
    print("Submitted answer: CHECK PASS")
else:
    print("Submitted answer (option 1 form): CHECK FAIL")
    print("Unique passing option:", passing[0] if len(passing) == 1 else "UNSUPPORTED")
